114	        owner.setTelephone(normalizedTelephone);
115	        owner.setEmail(normalizeEmail(owner.getEmail()));
116	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
117	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
118	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
119	        owner.setRegistrationDate(businessDate);
120	        long createdToday = this.clinicService.findAllOwners().stream()
121	            .map(Owner::getRegistrationDate)
122	            .filter(businessDate::equals)
123	            .count();
124	        if (createdToday >= 100) {
125	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
126	                "The maximum number of owners for today has already been reached");
127	        }
128	        owner.setBulkSignupWarning(createdToday > 80);
129	        String lastNameKey = normalizeForHousehold(owner.getLastName());
130	        String addressKey = normalizeForHousehold(owner.getAddress());
131	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
132	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(lastNameKey)
133	                && normalizeForHousehold(existing.getAddress()).equals(addressKey))
134	            .toList();
135	        String householdId = null;
136	        if (!householdMembers.isEmpty() && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
137	            householdId = householdId(lastNameKey, addressKey);
138	            owner.setHouseholdId(householdId);
139	        }
140	        // All duplicate detection is now expressed through the single derived identityKey
141	        // (telephone|email|householdId); a new owner is rejected only when its whole key matches.
142	        String identityKey = owner.getIdentityKey();
143	        boolean identityInUse = this.clinicService.findAllOwners().stream()
144	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
145	        if (identityInUse) {
146	            throw new ResponseStatusException(HttpStatus.CONFLICT,
147	                "An owner with this identity already exists");
148	        }
149	        if (householdId != null) {
150	            for (Owner member : householdMembers) {
151	                if (!householdId.equals(member.getHouseholdId())) {
152	                    member.setHouseholdId(householdId);
153	                    this.clinicService.saveOwner(member);
154	                }
155	            }
156	        }
157	        String cityKey = normalizeForHousehold(owner.getCity());
158	        long cityCount = this.clinicService.findAllOwners().stream()
159	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
160	            .count();
161	        if (cityCount >= 50) {
162	            throw new ResponseStatusException(HttpStatus.CONFLICT,
163	                "This city already has the maximum number of owners");
164	        }
165	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
166	        owner.setHouseholdSize(householdMembers.size() + 1);
167	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
168	        this.clinicService.saveOwner(owner);
169	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
170	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
171	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel());
172	        headers.setLocation(UriComponentsBuilder.newInstance()
173	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
174	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
175	    }
176	
177	    /**
178	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
179	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
180	     * to the effective registration date (whether supplied in the request or defaulted to the server
181	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
182	     * business day.
183	     *
184	     * @param date the effective registration date
185	     * @return the same date if it is a weekday, otherwise the following Monday
186	     */
187	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
188	        return switch (date.getDayOfWeek()) {
189	            case SATURDAY -> date.plusDays(2);
190	            case SUNDAY -> date.plusDays(1);
191	            default -> date;
192	        };
193	    }
194	
195	    /**
196	     * Counts the owners that already exist (before the current create) whose first and last names
197	     * both match the supplied names, compared case-insensitively. The returned value is captured on
198	     * the new owner at creation time and does not change as further owners are added later.
199	     *
200	     * @param firstName the new owner's first name
201	     * @param lastName  the new owner's last name
202	     * @return the number of pre-existing namesake owners
203	     */
204	    private int namesakeCount(String firstName, String lastName) {
205	        return (int) this.clinicService.findAllOwners().stream()
206	            .filter(existing -> existing.getFirstName() != null
207	                && existing.getFirstName().equalsIgnoreCase(firstName)
208	                && existing.getLastName() != null
209	                && existing.getLastName().equalsIgnoreCase(lastName))
210	            .count();
211	    }
212	
213	    /**
214	     * Builds the customer code for a new owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'} where
215	     * {@code CITY3} is the upper-cased first three letters of the city, {@code LAST3} is the
216	     * upper-cased first three letters of the last name, and {@code NNNN} is a per-city 4-digit
217	     * zero-padded sequence equal to one more than the number of owners already in that city
218	     * (e.g. {@code 'SYD-SMI-0007'}).
219	     *
220	     * @param city     the owner's city
221	     * @param lastName the owner's last name
222	     * @return the assigned customer code
223	     */
224	    private String nextCustomerCode(String city, String lastName) {
225	        String cityPrefix = first3Upper(city);
226	        String lastPrefix = first3Upper(lastName);
227	        String cityKey = normalizeForHousehold(city);
228	        long sequence = this.clinicService.findAllOwners().stream()
229	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
230	            .count() + 1L;
231	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
232	    }
233	
234	    /**
235	     * Returns the upper-cased first three characters of {@code value}, or fewer if the value is
236	     * shorter. A {@code null} value yields the empty string.
237	     *
238	     * @param value the source value
239	     * @return the upper-cased first three characters
240	     */
241	    private String first3Upper(String value) {
242	        String v = (value == null ? "" : value);
243	        return v.substring(0, Math.min(3, v.length())).toUpperCase(java.util.Locale.ROOT);
244	    }
245	
246	    /**
247	     * Normalizes a street address applied whenever an owner is created: leading and trailing
248	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
249	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
250	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
251	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
252	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
253	     * {@code '12 MAIN STREET'}.
254	     *
255	     * @param address the raw address as submitted, or {@code null} when absent
256	     * @return the normalized address, or the empty string when the value is blank
257	     */
258	    private String normalizeAddress(String address) {
259	        String collapsed = (address == null ? "" : address)
260	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
261	        if (collapsed.isEmpty()) {
262	            return "";
263	        }
264	        String[] tokens = collapsed.split(" ");
265	        for (int i = 0; i < tokens.length; i++) {
266	            switch (tokens[i]) {
267	                case "ST" -> tokens[i] = "STREET";
268	                case "RD" -> tokens[i] = "ROAD";
269	                case "AVE" -> tokens[i] = "AVENUE";
270	                default -> { }
271	            }
272	        }
273	        return String.join(" ", tokens);
274	    }
275	
276	    /**
277	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
278	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
279	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
280	     * empty string.
281	     *
282	     * @param value the raw value (last name or address) as submitted
283	     * @return the normalized comparison key
284	     */
285	    private String normalizeForHousehold(String value) {
286	        if (value == null) {
287	            return "";
288	        }
289	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
290	    }
291	
292	    /**
293	     * Derives the stable shared household identifier for a household, keyed on the normalized last
294	     * name and address. Because it is a pure function of those normalized keys, every owner in the
295	     * same household deterministically computes the same value. The identifier is the first 12
296	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
297	     * (the separator prevents distinct name/address pairs from colliding).
298	     *
299	     * @param lastNameKey the normalized last-name comparison key
300	     * @param addressKey  the normalized address comparison key
301	     * @return the stable household identifier
302	     */
303	    private String householdId(String lastNameKey, String addressKey) {
304	        String seed = lastNameKey + "�" + addressKey;
305	        try {
306	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
307	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
308	            StringBuilder sb = new StringBuilder(digest.length * 2);
309	            for (byte b : digest) {
310	                sb.append(String.format("%02x", b));
311	            }
312	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
313	        }
314	        catch (java.security.NoSuchAlgorithmException e) {
315	            throw new IllegalStateException("SHA-256 not available", e);
316	        }
317	    }
318	
319	    /**
320	     * The exact number of national (subscriber) digits required for a given country calling code,
321	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
322	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
323	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
324	     */
325	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
326	        java.util.Map.of("61", 9, "1", 10);
327	
328	    /**
329	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
330	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
331	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
332	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
333	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
334	     * is stored as {@code '+61412345678'}.
335	     *
336	     * <p>In addition, when the number's country code has a fixed national-number length (see
337	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
338	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
339	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
340	     *
341	     * @param telephone the raw telephone number as submitted
342	     * @return the normalized E.164 telephone number
343	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
344	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
345	     *         for its country code
346	     */
347	    private String normalizeTelephone(String telephone) {
348	        String raw = telephone == null ? "" : telephone.trim();
349	        String digits = raw.replaceAll("\\D", "");
350	        String e164;
351	        if (raw.startsWith("+")) {
352	            e164 = "+" + digits;
353	        } else {
354	            if (digits.startsWith("0")) {
355	                digits = digits.substring(1);
356	            }
357	            e164 = "+61" + digits;
358	        }
359	        int digitCount = e164.length() - 1;
360	        if (digitCount < 8 || digitCount > 15) {
361	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
362	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
363	        }
364	        validateNationalNumberLength(e164);
365	        return e164;
366	    }
367	
368	    /**
369	     * Validates that an E.164 number's national-number length is correct for its country code.
370	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
371	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
372	     * following it must match exactly. Country codes without a fixed length are left unchecked.
373	     *
374	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
375	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
376	     *         for the country code
377	     */
378	    private void validateNationalNumberLength(String e164) {
379	        String allDigits = e164.substring(1);
380	        String bestCode = null;
381	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
382	            if (allDigits.startsWith(code)
383	                    && (bestCode == null || code.length() > bestCode.length())) {
384	                bestCode = code;
385	            }
386	        }
387	        if (bestCode == null) {
388	            return;
389	        }
390	        int nationalLength = allDigits.length() - bestCode.length();
391	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
392	        if (nationalLength != required) {
393	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
394	                "Telephone for country code '+" + bestCode + "' must have " + required
395	                    + " national digits");
396	        }
397	    }
398	
399	    /**
400	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
401	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
402	     * (absent) or already valid.
403	     *
404	     * @param email the email address as submitted, or {@code null} when absent
405	     * @return the lower-cased email, or {@code null} when absent
406	     */
407	    private String normalizeEmail(String email) {
408	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
409	    }
410	
411	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
412	    @Override
413	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
414	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
415	        if (currentOwner == null) {
416	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
417	        }
418	        currentOwner.setAddress(ownerFieldsDto.getAddress());
419	        currentOwner.setCity(ownerFieldsDto.getCity());
420	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
421	        currentOwner.setLastName(ownerFieldsDto.getLastName());
422	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
423	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
424	        this.clinicService.saveOwner(currentOwner);
425	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
426	    }
427	
428	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
429	    @Transactional
430	    @Override
431	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
432	        Owner owner = this.clinicService.findOwnerById(ownerId);
433	        if (owner == null) {
434	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
435	        }
436	        this.clinicService.deleteOwner(owner);
437	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
438	    }
439	
440	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
441	    @Override
442	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
443	        Owner owner = this.clinicService.findOwnerById(ownerId);
444	        if (owner == null) {
445	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
446	        }
447	        HttpHeaders headers = new HttpHeaders();
448	        Pet pet = petMapper.toPet(petFieldsDto);
449	        owner.setId(ownerId);
450	        pet.setOwner(owner);
451	        pet.getType().setName(null);
452	        this.clinicService.savePet(pet);
453	        PetDto petDto = petMapper.toPetDto(pet);
454	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
455	            .buildAndExpand(pet.getId()).toUri());
456	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
457	    }
458	
459	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
460	    @Override
461	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
462	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
463	        if (currentOwner != null) {
464	            Pet currentPet = this.clinicService.findPetById(petId);
465	            if (currentPet != null) {
466	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
467	                currentPet.setName(petFieldsDto.getName());
468	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
469	                this.clinicService.savePet(currentPet);
470	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
471	            }
472	        }
473	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
474	    }
